import CryptoKit
import Foundation
import WebKit

/// Compiles the bundled EasyList/EasyPrivacy WebKit content-blocker JSON
/// (`QuiperShared/Resources/ContentBlockers/*.json`, regenerated by
/// `scripts/update-blocklists.sh`) into `WKContentRuleList`s and keeps them
/// installed on every registered user content controller while ad and tracker
/// blocking is enabled.
///
/// As a second layer for ads that declarative rules cannot reach, two
/// bundled GPL userscripts are injected at document start into the page's own
/// JS world: AdGuard Extra (adblock-circumvention defence, Twitch) and
/// AdGuard's Block YouTube Ads script (YouTube video ads). Their execution is
/// gated on the presence of a flag script message handler on the controller,
/// so the toggle works without removing the scripts themselves (WebKit has no
/// per-script removal). Marker-free webviews never receive any layer.
///
/// `WKContentRuleListStore` persists compiled lists on disk keyed by
/// identifier. Each pass fingerprints the bundled rule JSONs and, while that
/// fingerprint matches, reads the compiled lists back with
/// `lookUpContentRuleList` instead of recompiling ~14 MB of rules; a content
/// change (weekly blocklist regeneration) or a cache miss recompiles and
/// re-stores them.
///
/// Registration happens at the single webview creation gates (macOS
/// `WebViewManager.makeManagedWebView`, iOS `WebViewSession.init`). Marker-free
/// ("private") webviews must never be registered: content rule lists change
/// page behaviour in ways a page can observe.
@MainActor
final class ContentBlockerManager {
    static let shared = ContentBlockerManager()

    struct RuleListSource {
        /// Stable identifier used by `WKContentRuleListStore`'s on-disk cache.
        let identifier: String
        /// Bundled JSON file name, without the `.json` extension.
        let resourceName: String
    }

    static let sources: [RuleListSource] = [
        RuleListSource(identifier: "app.sassanh.quiper.content-blocker.ads", resourceName: "blocker-ads"),
        RuleListSource(identifier: "app.sassanh.quiper.content-blocker.privacy", resourceName: "blocker-privacy"),
    ]

    /// The injected userscripts check for this handler via
    /// `window.webkit.messageHandlers` before doing anything; the handler is
    /// present exactly while blocking is enabled, which makes the toggle work
    /// without removing the scripts. It installs at registration — before any
    /// compilation — so even a launch-restored tab's first navigation sees
    /// it.
    /// Injected scripts also report uncaught errors here, so failures
    /// surface in the system log.
    nonisolated static let scriptGateHandlerName = "quiperContentBlocking"
    /// Mirrors AdGuard Extra's upstream `@exclude` directives: the script
    /// manager enforced these for Tampermonkey users, so we replicate them.
    nonisolated static let extraScriptExcludes: [String] = [
        "*://captcha-api.yandex.ru/*",
        "*://ya.ru/showcaptcha?",
        "*://mil.ru/*",
        "*wikipedia.org*",
        "*icloud.com*",
        "*hangouts.google.com*",
        "*www.facebook.com/plugins/*",
        "*www.facebook.com/v*/plugins*",
        "*disqus.com/embed/comments*",
        "*vk.com/widget*",
        "*twitter.com/intent/*",
        "*www.youtube.com/embed/*",
        "*player.vimeo.com*",
        "*coub.com/embed*",
        "*staticxx.facebook.com/connect/xd_arbiter/*",
        "*vk.com/q_frame*",
        "*tpc.googlesyndication.com*",
        "*syndication.twitter.com*",
        "*platform.twitter.com*",
        "*tutosdeath.blogspot.com*",
        "*notifications.google.com*",
        "*google.com/recaptcha/*",
        "*bizmania.ru/*",
        "*bunkr.cr/*",
    ]

    /// Mirrors the user-facing "Block ads & trackers" setting.
    private(set) var isEnabled: Bool
    /// Loads the bundled rule JSON for a resource name; injectable for tests.
    private let ruleJSONProvider: (String) -> String?
    /// Loads the bundled AdGuard Extra userscript; injectable for tests.
    private let extraScriptProvider: () -> String?
    /// Loads the bundled Block YouTube Ads userscript; injectable for tests.
    private let youtubeScriptProvider: () -> String?

    private var compiledLists: [WKContentRuleList] = []
    /// Single-flight compile: concurrent callers share one pass instead of
    /// running parallel compiles for the same identifiers, which race on the
    /// store's on-disk files. Cleared when the pass ends so a failed pass
    /// can retry.
    private var compileTask: Task<Int, Never>?
    /// Disk-cache hits in the most recent pass; zero when it compiled.
    private(set) var ruleListCacheHits = 0
    /// UserDefaults key holding the fingerprint of the rule JSONs the store's
    /// compiled lists were built from. Cache metadata, not user settings.
    static let ruleListFingerprintKey = "contentBlocker.ruleListContentFingerprint"
    /// Weak: entries disappear with the webview that owns the controller.
    private let registeredControllers = NSHashTable<WKUserContentController>.weakObjects()
    /// Weak: guards against installing the same lists twice on one controller.
    private let installedControllers = NSHashTable<WKUserContentController>.weakObjects()
    /// Weak: guards against adding the injected user scripts twice; WebKit
    /// cannot remove individual scripts, so a duplicate would double-run.
    private let scriptInstalledControllers = NSHashTable<WKUserContentController>.weakObjects()
    /// Weak: guards against adding the gate handler twice to one controller
    /// (WebKit raises on a duplicate name).
    private let handlerInstalledControllers = NSHashTable<WKUserContentController>.weakObjects()
    /// Shared flag handler: its mere presence on a controller switches the
    /// injected scripts on; it also logs errors they report.
    private let scriptGateHandler = ScriptGateHandler()

    var compiledRuleListCount: Int { compiledLists.count }
    var registeredControllerCount: Int { registeredControllers.allObjects.count }

    init(
        isEnabled: Bool = true,
        ruleJSONProvider: @escaping (String) -> String? = ContentBlockerManager.bundledRuleJSON,
        extraScriptProvider: @escaping () -> String? = ContentBlockerManager.bundledExtraScriptSource,
        youtubeScriptProvider: @escaping () -> String? = ContentBlockerManager.bundledYouTubeScriptSource
    ) {
        self.isEnabled = isEnabled
        self.ruleJSONProvider = ruleJSONProvider
        self.extraScriptProvider = extraScriptProvider
        self.youtubeScriptProvider = youtubeScriptProvider
    }

    /// True while running under XCTest, so app startup paths can skip
    /// registration and test runs never compile the full bundled lists.
    static var isRunningTests: Bool {
        RuntimeEnvironment.areXCTestClassesLoaded && RuntimeEnvironment.isUnitTestRunner
    }

    /// Loads a bundled rule JSON. Synchronized Xcode groups may copy
    /// resources flattened or with their folder structure preserved, so both
    /// layouts are probed. `nonisolated`: a pure function over `Bundle.main`.
    nonisolated static func bundledRuleJSON(named resourceName: String) -> String? {
        let bundle = Bundle.main
        let url = bundle.url(forResource: resourceName, withExtension: "json", subdirectory: "ContentBlockers")
            ?? bundle.url(forResource: resourceName, withExtension: "json")
        guard let url, let data = try? Data(contentsOf: url) else {
            NSLog("[Quiper] ContentBlocker: missing bundled rule list %@.json", resourceName)
            return nil
        }
        return String(data: data, encoding: .utf8)
    }

    /// Loads a bundled userscript (`Resources/ContentBlockers/*.user.js`,
    /// refreshed by `scripts/update-blocklists.sh`). Both layouts probed like
    /// `bundledRuleJSON`.
    nonisolated static func bundledExtraScriptSource() -> String? {
        bundledUserScript(named: "adguard-extra.user")
    }

    nonisolated static func bundledYouTubeScriptSource() -> String? {
        bundledUserScript(named: "block-youtube-ads.user")
    }

    private nonisolated static func bundledUserScript(named resourceName: String) -> String? {
        let bundle = Bundle.main
        let url = bundle.url(forResource: resourceName, withExtension: "js", subdirectory: "ContentBlockers")
            ?? bundle.url(forResource: resourceName, withExtension: "js")
        guard let url, let data = try? Data(contentsOf: url) else {
            NSLog("[Quiper] ContentBlocker: missing bundled %@.js", resourceName)
            return nil
        }
        return String(data: data, encoding: .utf8)
    }

    /// Wraps AdGuard Extra in the gating Quiper prelude: the body only runs
    /// when the flag handler is present (blocking enabled) and the page URL
    /// is not on the upstream `@exclude` list. No userscript-sandbox shims:
    /// the upstream script guards its own globals (`typeof unsafeWindow`
    /// falls back to `window`) and never calls `GM_` APIs, so page-world
    /// injection needs no aliases. No strict mode: the upstream script runs
    /// non-strict under userscript managers. The gate handler installs at
    /// registration — before any navigation — so every document sees it at
    /// document start; the prelude does not poll for it.
    nonisolated static func makeExtraUserScript(rawSource: String) -> String {
        let excludes = extraScriptExcludes.joined(separator: "\", \"")
        return """
        (function () {
            var start = function (handlers) {
                var href = location.href;
                var excludes = ["\(excludes)"];
                for (var i = 0; i < excludes.length; i++) {
                    var pattern = excludes[i].replace(/[.+^${}()|[\\]\\\\?]/g, "\\\\$&").replace(/\\*/g, ".*");
                    if (new RegExp("^" + pattern + "$").test(href)) { return; }
                }
                try {
                    \(rawSource)
                } catch (e) {
                    try { handlers.\(scriptGateHandlerName).postMessage("adguard-extra: " + String(e)); } catch (ignored) {}
                }
            };
            var handlers = window.webkit && window.webkit.messageHandlers;
            if (handlers && handlers.\(scriptGateHandlerName)) { start(handlers); }
        })();
        """
    }

    /// Wraps AdGuard's Block YouTube Ads script in its gating prelude.
    /// Three site constraints are adapted around, without touching the
    /// upstream file:
    ///
    /// 1. At `.atDocumentStart` WebKit has not parsed `<head>` yet, while the
    ///    script unconditionally does `document.head.appendChild(...)` — so
    ///    the body is deferred until the parser creates `<head>`. The body's
    ///    layers are all reactive (DOM hiding, auto-skip) or need only to
    ///    precede the player's API calls (the `JSON.parse`/`Response.json`
    ///    interception), both of which hold at `<head>`-time.
    /// 2. YouTube enforces `require-trusted-types-for 'script'`, which
    ///    rejects plain-string `innerHTML` assignments — an identity
    ///    Trusted Types policy is installed and used to convert them. The
    ///    wrapper stays for the document's lifetime because the script's
    ///    observers keep assigning `innerHTML` later (logo retries).
    /// 3. The script injects its page logic via `script.innerHTML = code`,
    ///    which both the policy conversion and YouTube's `script-src`
    ///    (`'strict-dynamic'`, no insertion trust for us) would neutralise —
    ///    during the script's synchronous run window that one assignment is
    ///    routed through `eval` instead, which YouTube's CSP allows
    ///    (`'unsafe-eval'`).
    /// 4. The bundled script intercepts `JSON.parse` and `Response.json` but
    ///    not the page's initial inline player response, which arrives via a
    ///    plain `var ytInitialPlayerResponse = …` assignment — the first
    ///    video of a page load still started an ad break. The prelude
    ///    installs a window accessor for that assignment itself, and does so
    ///    at document start rather than in the deferred body: the body's
    ///    head-observed install ran as a microtask the parser's first inline
    ///    script could precede, letting the ads-laden object be stored before
    ///    the accessor replaced it. The declaration is var-style, so the
    ///    pre-installed accessor's setter catches it and strips
    ///    `adPlacements`/`playerAds` before the page reads them.
    ///
    /// Failures are reported through the flag handler so they reach the log.
    /// The adapted constraints install only on the script's own YouTube
    /// hosts: everywhere else the upstream script returns at its domain
    /// check before touching any adapted sink, so no other page gets the
    /// policy or the prototype wrapper. The gate handler installs at
    /// registration — before any navigation — so every document sees it at
    /// document start; the prelude does not poll for it.
    nonisolated static func makeYouTubeUserScript(rawSource: String) -> String {
        return """
        (function () {
            var handlers = null;
            var inWindow = false;
            var policy = null;
            var done = false;
            var observer = null;
            var initialHost = location.hostname;
            var isYouTubeHost = function () {
                return initialHost === "www.youtube.com" || initialHost === "m.youtube.com"
                    || initialHost === "music.youtube.com" || initialHost === "www.youtube-nocookie.com";
            };
            var stripInitialPlayerResponse = function (obj) {
                if (!obj || typeof obj !== "object") { return obj; }
                try {
                    if (Array.isArray(obj.adPlacements)) { obj.adPlacements = []; }
                    if (Array.isArray(obj.playerAds)) { obj.playerAds = []; }
                } catch (e) {}
                return obj;
            };
            var installInitialResponseInterceptor = function () {
                if (!isYouTubeHost()) { return; }
                var initialStored;
                try {
                    Object.defineProperty(window, "ytInitialPlayerResponse", {
                        configurable: true,
                        get: function () { return initialStored; },
                        set: function (value) { initialStored = stripInitialPlayerResponse(value); }
                    });
                } catch (e) {
                    try { handlers.\(scriptGateHandlerName).postMessage("youtube-ads initial: " + String(e)); } catch (ignored) {}
                }
            };
            var runPayload = function () {
                if (done) { return; }
                done = true;
                if (observer) { observer.disconnect(); observer = null; }
                if (isYouTubeHost()) {
                    if (window.trustedTypes && trustedTypes.createPolicy) {
                        try {
                            policy = trustedTypes.createPolicy("quiper-content-blocking", {
                                createHTML: function (s) { return s; },
                                createScript: function (s) { return s; }
                            });
                        } catch (e) {
                            try { handlers.\(scriptGateHandlerName).postMessage("youtube-ads policy: " + String(e)); } catch (ignored) {}
                        }
                    }
                    if (window.trustedTypes) {
                        var orig = Object.getOwnPropertyDescriptor(Element.prototype, "innerHTML");
                        if (orig) {
                            Object.defineProperty(Element.prototype, "innerHTML", {
                                configurable: true,
                                enumerable: orig.enumerable,
                                get: orig.get,
                                set: function (v) {
                                    if (inWindow && this && this.tagName === "SCRIPT") {
                                        var code = policy ? policy.createScript(String(v)) : String(v);
                                        (0, eval)(code);
                                        return;
                                    }
                                    if (policy && !(window.TrustedHTML && v instanceof TrustedHTML)) {
                                        v = policy.createHTML(String(v));
                                    }
                                    orig.set.call(this, v);
                                }
                            });
                        }
                    }
                }
                inWindow = true;
                try {
            \(rawSource)
                } catch (e) {
                    try { handlers.\(scriptGateHandlerName).postMessage("youtube-ads: " + String(e)); } catch (ignored) {}
                }
                inWindow = false;
                if (isYouTubeHost()) {
                    try { handlers.\(scriptGateHandlerName).postMessage("youtube-ads: active"); } catch (ignored) {}
                }
            };
            var boot = function () {
                handlers = window.webkit && window.webkit.messageHandlers;
                if (!handlers || !handlers.\(scriptGateHandlerName)) { return false; }
                installInitialResponseInterceptor();
                if (document.head) { runPayload(); }
                else {
                    observer = new MutationObserver(runPayload);
                    observer.observe(document.documentElement, { childList: true });
                }
                return true;
            };
            boot();
        })();
        """
    }

    // MARK: - Registration

    /// Tracks a controller for the whole blocking stack. Always call this
    /// for non-private webviews — even while blocking is disabled — so a
    /// later enable applies to existing tabs as well as new ones. While
    /// enabled, the injected scripts and the gate handler install right
    /// here: they need no compilation, and a document must see the gate from
    /// its very first script or it skips its blocking layer for life. Rule
    /// lists join whenever their (possibly still running) compile finishes.
    func register(_ controller: WKUserContentController) {
        registeredControllers.add(controller)
        guard isEnabled else { return }
        install(on: controller)
        if compiledLists.isEmpty {
            startCompilationIfNeeded()
        }
    }

    func isRegistered(_ controller: WKUserContentController) -> Bool {
        registeredControllers.contains(controller)
    }

    func isInstalled(on controller: WKUserContentController) -> Bool {
        installedControllers.contains(controller)
    }

    func areInjectedScriptsInstalled(on controller: WKUserContentController) -> Bool {
        scriptInstalledControllers.contains(controller)
    }

    func isGateHandlerInstalled(on controller: WKUserContentController) -> Bool {
        handlerInstalledControllers.contains(controller)
    }

    /// Applies the current enabled state to every registered controller.
    /// Idempotent: repeated calls with the same value do no work beyond the
    /// enabled case's install sweep, which is itself guarded per controller.
    func setEnabled(_ enabled: Bool) {
        isEnabled = enabled
        let controllers = registeredControllers.allObjects
        if enabled {
            guard !controllers.isEmpty else { return }
            // Scripts and gate handler install immediately; the lists below
            // only do so when their compilation has finished.
            for controller in controllers {
                install(on: controller)
            }
            if compiledLists.isEmpty {
                startCompilationIfNeeded()
            }
        } else {
            for controller in controllers {
                uninstall(from: controller)
            }
        }
    }

    // MARK: - Compilation

    private func startCompilationIfNeeded() {
        guard compileTask == nil, compiledLists.isEmpty else { return }
        Task { await compileRuleLists() }
    }

    /// Brings the compiled lists up to date — reusing the on-disk compiled
    /// copies while the bundled JSONs are unchanged, compiling otherwise —
    /// and installs the results on all registered controllers. Concurrent
    /// callers share one pass, so parallel compiles for the same identifier
    /// never race. Exposed so tests can await completion instead of polling.
    func compileRuleLists() async -> Int {
        if let inFlight = compileTask { return await inFlight.value }
        let task = Task { () -> Int in
            defer { self.compileTask = nil }
            return await self.compileAndInstall()
        }
        compileTask = task
        return await task.value
    }

    private func compileAndInstall() async -> Int {
        ruleListCacheHits = 0
        guard let store = WKContentRuleListStore.default() else {
            NSLog("[Quiper] ContentBlocker: WKContentRuleListStore unavailable; ads & trackers stay unblocked")
            return 0
        }
        var payloads: [(source: RuleListSource, json: String)] = []
        for source in Self.sources {
            guard let json = ruleJSONProvider(source.resourceName) else { continue }
            payloads.append((source, json))
        }
        // Fingerprint off the main actor: it hashes the full ~14 MB of JSON.
        let jsons = payloads.map(\.json)
        let fingerprint = await Task.detached(priority: .utility) {
            Self.ruleListFingerprint(jsons)
        }.value

        var lists: [WKContentRuleList] = []
        let cachedFingerprint = UserDefaults.standard.string(forKey: Self.ruleListFingerprintKey)
        if cachedFingerprint == fingerprint {
            for payload in payloads {
                guard let list = await lookUpContentRuleList(store, identifier: payload.source.identifier) else {
                    lists = []
                    break
                }
                lists.append(list)
                ruleListCacheHits += 1
            }
        }
        if ruleListCacheHits != payloads.count {
            // Changed content, cache miss, or an incomplete cache: compile.
            lists = []
            ruleListCacheHits = 0
            for payload in payloads {
                do {
                    let list = try await compileContentRuleList(
                        store,
                        identifier: payload.source.identifier,
                        json: payload.json
                    )
                    lists.append(list)
                } catch {
                    NSLog(
                        "[Quiper] ContentBlocker: failed to compile %@: %@",
                        payload.source.identifier,
                        String(describing: error)
                    )
                }
            }
            // Record the fingerprint only for a complete pass: a partial
            // result must not masquerade as a full cache on the next launch.
            if lists.count == payloads.count {
                UserDefaults.standard.set(fingerprint, forKey: Self.ruleListFingerprintKey)
            }
        }
        compiledLists = lists
        guard isEnabled else { return lists.count }
        for controller in registeredControllers.allObjects {
            install(on: controller)
        }
        return lists.count
    }

    /// Reads a previously compiled list back from the store. A miss or any
    /// lookup failure reports nil so the caller recompiles.
    private func lookUpContentRuleList(
        _ store: WKContentRuleListStore,
        identifier: String
    ) async -> WKContentRuleList? {
        await withCheckedContinuation { continuation in
            store.lookUpContentRuleList(forIdentifier: identifier) { list, _ in
                if list != nil {
                    NSLog("[Quiper] ContentBlocker: reused compiled cache for %@", identifier)
                }
                continuation.resume(returning: list)
            }
        }
    }

    /// Stable content fingerprint of the rule JSONs, keying the on-disk
    /// compile cache so regenerated blocklists recompile. `nonisolated`: a
    /// pure function, hashed off the main actor by the caller.
    nonisolated static func ruleListFingerprint(_ jsons: [String]) -> String {
        var hasher = SHA256()
        for json in jsons {
            hasher.update(data: Data(json.utf8))
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    private func compileContentRuleList(
        _ store: WKContentRuleListStore,
        identifier: String,
        json: String
    ) async throws -> WKContentRuleList {
        try await withCheckedThrowingContinuation { continuation in
            store.compileContentRuleList(forIdentifier: identifier, encodedContentRuleList: json) { list, error in
                if let list {
                    continuation.resume(returning: list)
                } else {
                    continuation.resume(throwing: error ?? CocoaError(.fileReadCorruptFile))
                }
            }
        }
    }

    // MARK: - Installation

    /// Brings one controller up to the current enabled state. The pieces are
    /// guarded independently: the scripts and the gate handler need no
    /// compiled lists and must exist before the controller's first
    /// navigation; the lists install whenever their compilation finished.
    /// Callers must only call this while enabled.
    private func install(on controller: WKUserContentController) {
        guard isEnabled else { return }
        ensureInjectedScripts(on: controller)
        if !handlerInstalledControllers.contains(controller) {
            controller.add(scriptGateHandler, name: Self.scriptGateHandlerName)
            handlerInstalledControllers.add(controller)
            NSLog("[Quiper] ContentBlocker: gate handler enabled on a webview")
        }
        guard !compiledLists.isEmpty, !installedControllers.contains(controller) else { return }
        for list in compiledLists {
            controller.add(list)
        }
        installedControllers.add(controller)
        NSLog("[Quiper] ContentBlocker: enabled %d rule list(s) on a webview", compiledLists.count)
    }

    private func uninstall(from controller: WKUserContentController) {
        if handlerInstalledControllers.contains(controller) {
            handlerInstalledControllers.remove(controller)
            // Removing the flag handler switches the injected scripts off
            // without touching them; WebKit cannot remove individual scripts.
            controller.removeScriptMessageHandler(forName: Self.scriptGateHandlerName)
            NSLog("[Quiper] ContentBlocker: gate handler disabled on a webview")
        }
        guard installedControllers.contains(controller) else { return }
        installedControllers.remove(controller)
        // WebKit removes rule lists by object, not by identifier.
        for list in compiledLists {
            controller.remove(list)
        }
    }

    /// Adds the gated injected user scripts once per controller while
    /// blocking is enabled. Inert when the flag handler is absent, but only
    /// shipped at all while blocking is on.
    private func ensureInjectedScripts(on controller: WKUserContentController) {
        guard !scriptInstalledControllers.contains(controller), !injectedUserScripts.isEmpty else { return }
        for script in injectedUserScripts {
            controller.addUserScript(script)
        }
        scriptInstalledControllers.add(controller)
        NSLog(
            "[Quiper] ContentBlocker: injected %d gated userscript(s) on a webview",
            injectedUserScripts.count
        )
    }

    /// Re-adds the injected scripts after an external
    /// `removeAllUserScripts()` wipe (engine script refreshes). Callers must
    /// only use this right after clearing the controller's scripts;
    /// WebKit offers no per-script removal, so duplicates are otherwise
    /// possible. Decided by what was shipped, not by the current toggle: a
    /// wipe while disabled must still restore the scripts, or the stale
    /// "installed" flag would block the next enable from ever re-adding
    /// them — leaving a controller with the gate handler but no scripts.
    func reinstallInjectedScripts(on controller: WKUserContentController) {
        guard scriptInstalledControllers.contains(controller),
              registeredControllers.contains(controller),
              !injectedUserScripts.isEmpty else { return }
        for script in injectedUserScripts {
            controller.addUserScript(script)
        }
    }

    /// The gated injected scripts, built once from the bundled userscripts.
    private lazy var injectedUserScripts: [WKUserScript] = {
        var scripts: [WKUserScript] = []
        if let raw = extraScriptProvider() {
            scripts.append(Self.makeUserScript(Self.makeExtraUserScript(rawSource: raw)))
        }
        if let raw = youtubeScriptProvider() {
            scripts.append(Self.makeUserScript(Self.makeYouTubeUserScript(rawSource: raw)))
        }
        if scripts.isEmpty {
            NSLog("[Quiper] ContentBlocker: no bundled userscripts found; script layer inactive")
        }
        return scripts
    }()

    private static func makeUserScript(_ source: String) -> WKUserScript {
        WKUserScript(
            source: source,
            injectionTime: .atDocumentStart,
            forMainFrameOnly: true,
            in: .page
        )
    }
}

/// Shared flag handler for the injected userscripts. Its presence on a
/// controller is the "blocking enabled" signal the scripts check; messages
/// are an activation heartbeat from the YouTube layer plus error reports
/// from the catch blocks, logged for diagnosis.
/// Stateless and shared across controllers; retains nothing.
private final class ScriptGateHandler: NSObject, WKScriptMessageHandler {
    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        NSLog("[Quiper] ContentBlocker: injected script reported: %@", String(describing: message.body))
    }
}
